#!/usr/bin/env python3
"""Keep the firmware icon rules in line with the Blueprint's icon tables.

The panel resolves the icon of an entity from its domain, device class and state with
ICON_RULES (components/nspanel_easy/icon_rules.h), a copy of two Blueprint tables:
`device_class_icons` (keyed "<domain>.<device_class>[-<state>]") and `nextion.icon.domain`
(keyed "<domain>", or "<domain>-<state>" for the sun's day/night icon). The Blueprint keeps its own
copy for the surfaces it still draws itself.

Usage:
  test_icon_rules.py BASE CANDIDATE   Check that icon_rules.h matches CANDIDATE (BASE is ignored;
                                      the argument keeps the calling convention of the other tests).
  test_icon_rules.py --write [BLUEPRINT]  Regenerate icon_rules.h from BLUEPRINT
                                          (default: nspanel_easy_blueprint.yaml).
"""

import re
import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parent))
import blueprint_metrics  # noqa: E402

ROOT = Path(__file__).resolve().parents[2]
HEADER = ROOT / "components" / "nspanel_easy" / "icon_rules.h"
ALL_ICONS = ROOT / "components" / "nspanel_easy" / "all_icons.h"
ENTRY = re.compile(r'\{"([^"]+)",\s*Icons::(MDI_[A-Z0-9_]+)\}')
SUN_TEMPLATE = re.compile(r'\{\{\s*"\\+u([0-9A-Fa-f]{4})"\s+if\s+sun_is_up\s+else\s+"\\+u([0-9A-Fa-f]{4})"\s*\}\}')


def find_key(node, key):
    """Return the first value stored under `key` anywhere in node."""
    if isinstance(node, dict):
        if key in node:
            return node[key]
        node = list(node.values())
    if isinstance(node, list):
        for item in node:
            found = find_key(item, key)
            if found is not None:
                return found
    return None


def constant(icon_name):
    """C++ constant of an MDI icon name in all_icons.h."""
    return "MDI_" + icon_name.upper().replace("-", "_")


def expected_rules(blueprint_path):
    """Rules from the Blueprint, as (key, constant) pairs in Blueprint order."""
    _, data = blueprint_metrics.load_blueprint(blueprint_path)
    device_class_icons = find_key(data, "device_class_icons")
    nextion = find_key(data, "nextion")
    all_icon_names = find_key(data, "all_icon_names")
    if not device_class_icons or not nextion or not all_icon_names:
        raise SystemExit("Icon tables not found in the Blueprint")
    names = all_icon_names.strip(",").split(",")
    rules = []
    for domain, entries in device_class_icons.items():
        for key, icon_name in entries.items():
            rules.append((f"{domain}.{key}", constant(icon_name)))

    def name_of(glyph, domain):
        position = ord(glyph) - 0xE000
        if not 0 <= position < len(names):
            raise SystemExit(f"Domain icon of '{domain}' is not an MDI codepoint")
        return constant(names[position])

    for domain, glyph in nextion["icon"]["domain"].items():
        # The sun icon is a template on the sun's own state: "<up>" if sun_is_up else "<down>"
        day_night = SUN_TEMPLATE.fullmatch(glyph.strip())
        if day_night:
            up, down = (chr(int(code, 16)) for code in day_night.groups())
            rules.append((f"{domain}-below_horizon", name_of(down, domain)))
            rules.append((domain, name_of(up, domain)))
        elif len(glyph) == 1:
            rules.append((domain, name_of(glyph, domain)))
        else:
            raise SystemExit(f"Domain icon of '{domain}' is neither a codepoint nor the sun template")
    return rules


def write(rules):
    """Write icon_rules.h."""
    lines = [
        "// icon_rules.h",
        "",
        "#pragma once",
        "",
        '#include "all_icons.h"',
        "",
        "/**",
        " * @file icon_rules.h",
        " * @brief Icon of an entity by domain, device class and state.",
        " *",
        " * Generated by .github/scripts/test_icon_rules.py --write from the Blueprint's",
        " * `device_class_icons` and `nextion.icon.domain`; do not edit by hand. CI fails",
        " * when it no longer matches the Blueprint, which keeps its own copy for the",
        " * surfaces it still draws itself.",
        " *",
        " * Keys, as the Blueprint keys them:",
        ' *   - "<domain>.<device_class>-<state>" (e.g. "binary_sensor.door-on");',
        ' *   - "<domain>.<device_class>" for button, event and sensor, whose device',
        " *     class icon does not depend on the state;",
        ' *   - "<domain>" for the domain default (e.g. "light").',
        " */",
        "",
        "namespace esphome::nspanel_easy {",
        "",
        "/// @brief One icon rule: a key and the icon it resolves to.",
        "struct IconRule {",
        "  const char *key;   ///< Rule key, as above",
        "  const char *icon;  ///< UTF-8 MDI codepoint",
        "};",
        "",
        "// clang-format off",
        "static constexpr IconRule ICON_RULES[] = {",
    ]
    lines += [f'    {{"{key}", Icons::{name}}},' for key, name in rules]
    lines += [
        "};",
        "// clang-format on",
        "",
        "}  // namespace esphome::nspanel_easy",
        "",
    ]
    HEADER.write_text("\n".join(lines), encoding="utf-8")


def main():
    args = sys.argv[1:]
    if args and args[0] == "--write":
        blueprint = args[1] if len(args) > 1 else str(ROOT / "nspanel_easy_blueprint.yaml")
        write(expected_rules(blueprint))
        print(f"Wrote {HEADER.relative_to(ROOT)}")
        return 0

    if len(args) != 2:
        print(__doc__)
        return 2
    expected = expected_rules(args[1])
    actual = ENTRY.findall(HEADER.read_text(encoding="utf-8"))
    known = set(re.findall(r"constexpr const char \*(MDI_[A-Z0-9_]+) =", ALL_ICONS.read_text(encoding="utf-8")))

    failures = [f"unknown icon constant {name} (rule '{key}')" for key, name in expected if name not in known]
    if actual != expected:
        missing = sorted(set(expected) - set(actual))
        extra = sorted(set(actual) - set(expected))
        failures += [f"missing in icon_rules.h: {key} -> {name}" for key, name in missing]
        failures += [f"not in the Blueprint: {key} -> {name}" for key, name in extra]
        if not missing and not extra:
            failures.append("same rules in a different order")
    for failure in failures:
        print(f"FAIL {failure}")
    print(f"{len(expected)} icon rules: {'FAIL' if failures else 'OK'}"
          + (" (regenerate with: python3 .github/scripts/test_icon_rules.py --write)" if failures else ""))
    return 1 if failures else 0


if __name__ == "__main__":
    sys.exit(main())
